mapper.select:
select t.ID_ as processInstanceId, t.BUSINESS_KEY_ as businessKey, t.KEY_ as processModelType, t.source_status as processStatus, t.ASSIGNEE_ as currentAssignerId, t.proj_code as projCode, t.proj_name as projName, t.contract_code as contractCode, t.biz_dept_id as bizDeptId, t.proj_sponsor_user_id as projSponsorUserId, t.lease_types as leaseTypes, bu2.user_name as projSponsorUserName, bu.user_name as currentAssignerName, bo.name as bizDeptName from ( select ahp.ID_, ahp.BUSINESS_KEY_, arp.KEY_, bs.source_status, aht.ASSIGNEE_, case arp.KEY_ when 'LeaseCreateFlow' then prbi.proj_code when 'LeaseModifyFlow' then prbi.proj_code when 'ContractCreateFlow' then cbi.proj_code when 'ContractModifyFlow' then cbi.proj_code when 'PaymentCreateFlow' then pbicbi.proj_code end as proj_code, case arp.KEY_ when 'LeaseCreateFlow' then prbi.proj_name when 'LeaseModifyFlow' then prbi.proj_name when 'ContractCreateFlow' then cbi.proj_name when 'ContractModifyFlow' then cbi.proj_name when 'PaymentCreateFlow' then pbicbi.proj_name end as proj_name, case arp.KEY_ when 'ContractCreateFlow' then cbi.contract_code when 'ContractModifyFlow' then cbi.contract_code when 'PaymentCreateFlow' then pbicbi.contract_code end as contract_code, case arp.KEY_ when 'LeaseCreateFlow' then prbi.biz_dept_id when 'LeaseModifyFlow' then prbi.biz_dept_id when 'ContractCreateFlow' then cbi.biz_dept_id when 'ContractModifyFlow' then cbi.biz_dept_id when 'PaymentCreateFlow' then pbicbi.biz_dept_id end as biz_dept_id, case arp.KEY_ when 'LeaseCreateFlow' then prbi.proj_sponsor_user_id when 'LeaseModifyFlow' then prbi.proj_sponsor_user_id when 'ContractCreateFlow' then cbi.proj_sponsor_user_id when 'ContractModifyFlow' then cbi.proj_sponsor_user_id when 'PaymentCreateFlow' then pbicbi.proj_sponsor_user_id end as proj_sponsor_user_id, case arp.KEY_ when 'LeaseCreateFlow' then prbi.biz_type when 'LeaseModifyFlow' then prbi.biz_type when 'ContractCreateFlow' then cbi.biz_type when 'ContractModifyFlow' then cbi.biz_type when 'PaymentCreateFlow' then pbicbi.biz_type end as biz_type, case arp.KEY_ when 'LeaseCreateFlow' then prbi.lease_types when 'LeaseModifyFlow' then prbi.lease_types when 'ContractCreateFlow' then concat('["', cbi.lease_type, '"]') when 'ContractModifyFlow' then concat('["', cbi.lease_type, '"]') when 'PaymentCreateFlow' then concat('["', pbicbi.lease_type, '"]') end as lease_types from act_hi_procinst as ahp left join act_re_procdef as arp on ahp.PROC_DEF_ID_ = arp.ID_ left join act_hi_taskinst as aht on ahp.ID_ = aht.PROC_INST_ID_ and aht.END_TIME_ is null left join business_status as bs on ahp.ID_ = bs.source_id and bs.source_type = 1 left join lease_item_info as lii on ahp.BUSINESS_KEY_ = lii.id and arp.KEY_ in ('LeaseCreateFlow', 'LeaseModifyFlow') left join proj_review_base_info as prbi on prbi.id = lii.proj_review_id and arp.KEY_ in ('LeaseCreateFlow', 'LeaseModifyFlow') left join contract_base_info as cbi on ahp.BUSINESS_KEY_ = cbi.id and arp.KEY_ in ('ContractCreateFlow', 'ContractModifyFlow') left join payment_base_info as pbi on ahp.BUSINESS_KEY_ = pbi.id and arp.KEY_ in ('PaymentCreateFlow') left join contract_base_info as pbicbi on pbi.contract_id = pbicbi.id and arp.KEY_ in ('PaymentCreateFlow') where 1 = 1 and arp.KEY_ in ('LeaseCreateFlow', 'LeaseModifyFlow', 'ContractCreateFlow', 'ContractModifyFlow', 'PaymentCreateFlow') and ahp.ID_ in
#{processInstanceId}
) as t left join bifrost_user as bu on t.t.ASSIGNEE_ = bu.id left join bifrost_user as bu2 on t.proj_sponsor_user_id = bu2.id left join bifrost_org as bo on t.biz_dept_id = bo.id

select
    *
from (
