from
) as t where 1 = 1 and t.bizType = 'ZL'

mapper.sql:
act_hi_procinst as ahp left join act_re_procdef as arp on ahp.PROC_DEF_ID_ = arp.ID_ left join business_status as bs on ahp.ID_ = bs.source_id and source_type = 1 left join ( select a.*, b.apply_credit_amount, c.risk_control_industry_classify as client_risk_control_industry_classify, d.name as biz_dept_name, e.user_name as proj_sponsor_user_name from proj_establish_base_info as a inner join proj_establish_lease_price as b on a.id = b.proj_establish_id left join corp_commerce_info as c on a.client_id = c.client_id left join bifrost_org as d on d.id = a.biz_dept_id left join bifrost_user as e on e.id = a.proj_sponsor_user_id
and a.biz_dept_id = #{bizDeptId}
and a.proj_sponsor_user_id = #{projSponsorUserId}
and c.risk_control_industry_classify in
#{item}
and a.lease_types like concat('%', #{leaseType}, '%')
) as pebi on ahp.BUSINESS_KEY_ = pebi.id and arp.KEY_ = 'ProjEstablishCreateFlow' left join ( select a.id as lease_item_info_id, aa.*, b.apply_credit_amount, c.risk_control_industry_classify as client_risk_control_industry_classify, d.name as biz_dept_name, e.user_name as proj_sponsor_user_name from lease_item_info as a inner join proj_review_base_info as aa on a.proj_review_id = aa.id inner join proj_review_lease_price as b on aa.id = b.project_id left join corp_commerce_info as c on aa.client_id = c.client_id left join bifrost_org as d on d.id = aa.biz_dept_id left join bifrost_user as e on e.id = aa.proj_sponsor_user_id
and aa.biz_dept_id = #{bizDeptId}
and aa.proj_sponsor_user_id = #{projSponsorUserId}
and c.risk_control_industry_classify in
#{item}
and aa.lease_types like concat('%', #{leaseType}, '%')
) as lii on ahp.BUSINESS_KEY_ = lii.lease_item_info_id and arp.KEY_ = 'LeaseCreateFlow' left join ( select a.*, b.apply_credit_amount, c.risk_control_industry_classify as client_risk_control_industry_classify, d.name as biz_dept_name, e.user_name as proj_sponsor_user_name from proj_review_base_info as a inner join proj_review_lease_price as b on a.id = b.project_id left join corp_commerce_info as c on a.client_id = c.client_id left join bifrost_org as d on d.id = a.biz_dept_id left join bifrost_user as e on e.id = a.proj_sponsor_user_id
and a.biz_dept_id = #{bizDeptId}
and a.proj_sponsor_user_id = #{projSponsorUserId}
and c.risk_control_industry_classify in
#{item}
and a.lease_types like concat('%', #{leaseType}, '%')
) as prbi on ahp.BUSINESS_KEY_ = prbi.id and arp.KEY_ = 'ProjReviewCreateFlow' left join ( select a.*, b.apply_credit_amount as contract_amount, c.risk_control_industry_classify as client_risk_control_industry_classify, d.name as biz_dept_name, e.user_name as proj_sponsor_user_name from contract_base_info as a inner join contract_lease_price as b on a.id = b.contract_id left join corp_commerce_info as c on a.client_id = c.client_id left join bifrost_org as d on d.id = a.biz_dept_id left join bifrost_user as e on e.id = a.proj_sponsor_user_id
and a.biz_dept_id = #{bizDeptId}
and a.proj_sponsor_user_id = #{projSponsorUserId}
and c.risk_control_industry_classify in
#{item}
and a.lease_type = #{leaseType}
) as cbi on ahp.BUSINESS_KEY_ = cbi.id and arp.KEY_ = 'ContractCreateFlow' left join ( select a.*, b.proj_code, b.proj_name, b.proj_sponsor_user_id as con_proj_sponsor_user_id, b.biz_type, b.lease_type as con_lease_type, aa.actual_pay, aa.min_pay_date, c.risk_control_industry_classify as client_risk_control_industry_classify, d.name as biz_dept_name, e.user_name as proj_sponsor_user_name from payment_base_info as a inner join contract_base_info as b on a.contract_id = b.id left join (select min(paid_in_date) as min_pay_date, sum(paid_in_amount) as actual_pay, payment_id from payment_actual_detail group by payment_id) as aa on a.id = aa.payment_id left join corp_commerce_info as c on b.client_id = c.client_id left join bifrost_org as d on d.id = b.biz_dept_id left join bifrost_user as e on e.id = b.proj_sponsor_user_id
and b.biz_dept_id = #{bizDeptId}
and b.proj_sponsor_user_id = #{projSponsorUserId}
and c.risk_control_industry_classify in
#{item}
and b.lease_type = #{leaseType}
) as pbi on ahp.BUSINESS_KEY_ = pbi.id and arp.KEY_ in ('PaymentCreateFlow', 'PaymentActualDetailFlow')
